using System;using System.IO;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;
[Serializable] public class SourcePart {public string id,cutout_resource,cutout_sha256,baseline_mesh_resource,baseline_mesh_sha256,baseline_texture_resource,selected_mesh_resource,selected_mesh_sha256,selected_texture_resource;public float[] bbox,centroid;public bool fallback,checked_rasters;public float[] hinge,host_basis,source_face_normal;public string selected_texture_sha256,baseline_texture_sha256;public float host_z;public int quantity;}
[Serializable] public class SourcePartsConfig {public string topic,basis;public float page_width;public float[] source_size,reference_crop;public SourcePart[] parts;}
// Actual learned assets with explicitly authored rigid motion, not a recovered skeleton/physics.
public class SourcePartsScene:MonoBehaviour {
 public SourcePartsConfig config;public bool flat,playing;public float parameter,time;public TextMesh label;
 public readonly List<Transform> pivots=new List<Transform>();readonly List<GameObject> planes=new List<GameObject>(),volumes=new List<GameObject>();readonly List<Mesh> owned=new List<Mesh>();readonly List<Material> mats=new List<Material>();
 public static string Hash(byte[] b){using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 public static void RequireHash(byte[] bytes,string expected){if(Hash(bytes)!=expected)throw new Exception("Source asset SHA mismatch");}
 public static Vector3 Basis(Vector3 v,float degrees){float a=degrees*Mathf.Deg2Rad,c=Mathf.Cos(a),s=Mathf.Sin(a);return new Vector3(c*v.x-s*v.y,s*v.x+c*v.y,-v.z);}
 public Vector3 Pixel(float x,float y){return new Vector3((x/config.source_size[0]-.5f)*config.page_width,(config.source_size[1]*.5f-y)*config.page_width/config.source_size[0],-.001f);}
 public void Configure(CatalogItem item){var text=Resources.Load<TextAsset>(item.source_parts_file);if(!text||Hash(text.bytes)!=item.source_parts_sha256)throw new Exception("Source-part config hash mismatch");config=JsonUtility.FromJson<SourcePartsConfig>(text.text);if(config.parts.Length<2||config.parts.Length>5)throw new Exception("Invalid source form conservation");flat=item.source_parts_mode=="2d";
  foreach(var p in config.parts){if(p.checked_rasters){var cut=Resources.Load<TextAsset>(p.cutout_resource+"-hashbytes");if(!cut)throw new Exception("Missing checked source RGBA");RequireHash(cut.bytes,p.cutout_sha256);var tex=Resources.Load<TextAsset>(p.selected_texture_resource+"-hashbytes");if(!tex)throw new Exception("Missing checked source texture");RequireHash(tex.bytes,p.selected_texture_sha256);}
   var pivot=new GameObject("Actual source centroid "+p.id).transform;pivot.SetParent(transform,false);pivots.Add(pivot);var plane=new GameObject("Exact learned RGBA 2.5D "+p.id);plane.transform.SetParent(pivot,false);var mesh=new Mesh();float w=(p.bbox[2]-p.bbox[0])*config.page_width/config.source_size[0],h=(p.bbox[3]-p.bbox[1])*config.page_width/config.source_size[0];mesh.vertices=new[]{new Vector3(-w/2,-h/2,0),new Vector3(w/2,-h/2,0),new Vector3(w/2,h/2,0),new Vector3(-w/2,h/2,0)};mesh.uv=new[]{new Vector2(0,0),new Vector2(1,0),new Vector2(1,1),new Vector2(0,1)};mesh.triangles=new[]{0,2,1,0,3,2};mesh.RecalculateNormals();owned.Add(mesh);plane.AddComponent<MeshFilter>().sharedMesh=mesh;ApplyTexture(plane,p.cutout_resource);plane.transform.localPosition=new Vector3(((p.bbox[0]+p.bbox[2])/2-p.centroid[0])*config.page_width/config.source_size[0],-((p.bbox[1]+p.bbox[3])/2-p.centroid[1])*config.page_width/config.source_size[0],0);planes.Add(plane);
   // Both baseline and selected bytes are validated, blue never displayed as an ideal sphere.
   LoadMesh(p.baseline_mesh_resource,p.baseline_mesh_sha256,false);var actual=LoadMesh(p.selected_mesh_resource,p.selected_mesh_sha256,true);if(p.fallback){volumes.Add(null);continue;}var volume=new GameObject("Actual unrigged selected Hunyuan "+p.id);volume.transform.SetParent(pivot,false);volume.AddComponent<MeshFilter>().sharedMesh=actual;ApplyTexture(volume,p.selected_texture_resource);var b=actual.bounds;float scale=Mathf.Max(w,h)/Mathf.Max(b.size.x,b.size.y,b.size.z);volume.transform.localScale=Vector3.one*scale;volume.transform.localPosition=new Vector3(-b.center.x*scale,-b.center.y*scale,-b.max.z*scale);volumes.Add(volume);
  }
  var g=new GameObject("Source parts controls and provenance");g.transform.SetParent(transform,false);g.transform.localPosition=new Vector3(0,-.158f,-.005f);label=g.AddComponent<TextMesh>();label.characterSize=.002f;label.fontSize=38;label.anchor=TextAnchor.MiddleCenter;label.alignment=TextAlignment.Center;Reset();Sample();
 }
 Mesh LoadMesh(string name,string expected,bool keep){var data=Resources.Load<TextAsset>(name);if(!data||Hash(data.bytes)!=expected)throw new Exception("Source-part mesh SHA mismatch "+name);using(var r=new BinaryReader(new MemoryStream(data.bytes))){int n=r.ReadInt32(),f=r.ReadInt32();if(n<=0||f<=0||data.bytes.Length!=8+n*24+f*12)throw new Exception("Source-part layout");var v=new Vector3[n];var c=new Color32[n];var ix=new int[f*3];var uv=new Vector2[n];for(int i=0;i<n;i++)v[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());for(int i=0;i<n;i++)c[i]=new Color32(r.ReadByte(),r.ReadByte(),r.ReadByte(),r.ReadByte());for(int i=0;i<ix.Length;i++)ix[i]=r.ReadInt32();for(int i=0;i<n;i++)uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());if(!keep)return null;var m=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,vertices=v,colors32=c,triangles=ix,uv=uv};m.RecalculateBounds();m.RecalculateNormals();owned.Add(m);return m;}}
 void ApplyTexture(GameObject g,string resource){var tex=Resources.Load<Texture2D>(resource);if(!tex)throw new Exception("Missing source-part raster "+resource);var mat=new Material(Resources.Load<Shader>("CatalogSurface"));mat.SetTexture("_BaseMap",tex);mats.Add(mat);g.AddComponent<MeshRenderer>().sharedMaterial=mat;}
 public void Reset(){time=0;parameter=0;playing=false;}
 public void ToggleMode(){flat=!flat;Sample();Debug.Log("CATALOG source-part representation="+(flat?"exactRGBA2.5D":"qualitySelected3D"));}
 public void Axes(Vector2 left,Vector2 right,float dt){parameter=Mathf.Clamp01(parameter+right.x*dt*.5f);}
 public void Sample(){bool solar=config.topic=="solar-system";int sun=Array.FindIndex(config.parts,p=>p.id=="solar-sun");Vector3 center=solar?Pixel(config.parts[sun].centroid[0],config.parts[sun].centroid[1]):Vector3.zero;
  for(int i=0;i<pivots.Count;i++){var p=config.parts[i];var pos=Pixel(p.centroid[0],p.centroid[1]);if(solar&&i!=sun){float a=time*(.3f+parameter*1.2f)/(i+1),dx=pos.x-center.x,dy=pos.y-center.y;pos=new Vector3(center.x+dx*Mathf.Cos(a)-dy*Mathf.Sin(a),center.y+dx*Mathf.Sin(a)+dy*Mathf.Cos(a),pos.z);}if(config.topic=="arithmetic"){float mix=parameter;int index=i<2?i:i-2;var target=new Vector3(i<2?-.057f+index*.025f:.022f+index*.025f,-.035f,pos.z);pos=Vector3.Lerp(pos,target,mix);}Quaternion rotation=Quaternion.identity;
   if(config.topic=="cell"&&i>0){pos.x+=(i==1?-1:1)*parameter*.03f;pos.z-=parameter*(i==1?.015f:.025f);}
   if(config.topic=="dna")pos.x+=(i==0?-1:1)*parameter*.035f;
   if(config.topic=="machine")rotation=Quaternion.AngleAxis(time*(.3f+parameter*2)*Mathf.Rad2Deg*(i==0?1:-1),Vector3.back);
   if(config.topic=="origami"){if(p.hinge==null||p.hinge.Length!=4)throw new Exception("Missing authored visible-edge hinge");var hinge=Pixel(p.hinge[0],p.hinge[1]);var axis=(Pixel(p.hinge[2],p.hinge[3])-hinge).normalized;rotation=Quaternion.AngleAxis(parameter*90*(i==0?1:-1),axis);pos=hinge+rotation*(pos-hinge);}
   pivots[i].localPosition=pos;pivots[i].localRotation=rotation;planes[i].SetActive(flat||p.fallback);if(volumes[i])volumes[i].SetActive(!flat);}
  int fallbacks=Array.FindAll(config.parts,p=>p.fallback).Length;string action=config.topic=="solar-system"?"orbit speed":config.topic=="arithmetic"?"2+3 grouping":config.topic=="cell"?"visible compartment explode":config.topic=="dna"?"visible strand separation":config.topic=="machine"?"equal opposite gear rate":"authored visible-edge fold";
  string scope=config.topic=="solar-system"?"Sun + four forms, blue hidden sphere unrecovered":config.topic=="arithmetic"?"Conserved five source columns = 2+3, not ten units":config.topic=="cell"?"Membrane/organelle group exact RGBA, no anatomy rig":config.topic=="dna"?"Two source strands; no fabricated bonds/hidden connectivity":config.topic=="machine"?"PCA-front actual gears; no calibrated transmission":"Authored visible crease, no recovered paper rig; right RGBA";
  label.text=config.topic+" · "+(flat?config.parts.Length+" exact source RGBA forms · 2.5D":(config.parts.Length-fallbacks)+" actual inferred meshes + "+fallbacks+" exactRGBA fallbacks")+"\nA: pause/play · L-stick click: 2.5D/3D · R-stick: "+action+" "+parameter.ToString("F2")+" · B: reset · X/Y: scene\nAuthored rigid mechanics, not learned rig/calibration; "+scope;

 }
 void Update(){if(playing)time+=Mathf.Min(Time.deltaTime,.05f);Sample();}
 void OnDestroy(){foreach(var m in owned)if(m){if(Application.isPlaying)Destroy(m);else DestroyImmediate(m);}foreach(var m in mats)if(m){if(Application.isPlaying)Destroy(m);else DestroyImmediate(m);}}
}
